BEGIN;
SELECT plan(33);
INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES
('97000000-0000-4000-8000-000000000001','meeting-staff@example.com','{"full_name":"Meeting staff","company_name":"Meeting tests"}'),
('97000000-0000-4000-8000-000000000002','meeting-owner@example.com','{"full_name":"Meeting owner","company_name":"Temporary test"}');
INSERT INTO clients(id,name,workspace_id,created_by) SELECT '97000000-0000-4000-8000-000000000011','Meeting R4',workspace_id,user_id FROM profiles WHERE user_id='97000000-0000-4000-8000-000000000001';
INSERT INTO clients(id,name,workspace_id,created_by) SELECT '97000000-0000-4000-8000-000000000012','Other client',workspace_id,user_id FROM profiles WHERE user_id='97000000-0000-4000-8000-000000000001';
UPDATE profiles SET workspace_id=(SELECT workspace_id FROM clients WHERE id='97000000-0000-4000-8000-000000000011'),client_id='97000000-0000-4000-8000-000000000011' WHERE user_id='97000000-0000-4000-8000-000000000002';
INSERT INTO organizations(id,tenant_id,name,kind) SELECT '97000000-0000-4000-8000-000000000031',workspace_id,name,'owner' FROM clients WHERE id='97000000-0000-4000-8000-000000000011';
INSERT INTO portal_memberships(tenant_id,user_id,organization_id,portal_kind) SELECT workspace_id,'97000000-0000-4000-8000-000000000002','97000000-0000-4000-8000-000000000031','owner' FROM clients WHERE id='97000000-0000-4000-8000-000000000011';
INSERT INTO permission_templates(id,tenant_id,name) SELECT '97000000-0000-4000-8000-000000000041',workspace_id,'Meeting editor test' FROM clients WHERE id='97000000-0000-4000-8000-000000000011';
INSERT INTO permission_template_grants(template_id,module,action,level) VALUES('97000000-0000-4000-8000-000000000041','meetings','edit','admin');
INSERT INTO user_template_assignments(tenant_id,user_id,template_id) SELECT workspace_id,'97000000-0000-4000-8000-000000000001','97000000-0000-4000-8000-000000000041' FROM clients WHERE id='97000000-0000-4000-8000-000000000011';
INSERT INTO projects(id,client_id,name,project_type,workspace_id,created_by) SELECT '97000000-0000-4000-8000-000000000021',id,'Sewer','construction',workspace_id,created_by FROM clients WHERE id='97000000-0000-4000-8000-000000000011';
INSERT INTO projects(id,client_id,name,project_type,workspace_id,created_by) SELECT '97000000-0000-4000-8000-000000000022',id,'Unrelated','consulting',workspace_id,created_by FROM clients WHERE id='97000000-0000-4000-8000-000000000012';
SELECT set_config('request.jwt.claims','{"sub":"97000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT ok(client_meeting_can_edit('97000000-0000-4000-8000-000000000011'),'template-authorized staff can edit');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','create','{"id":"97000000-0000-4000-8000-000000000051"}')$$,'create meeting');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','save','{"id":"97000000-0000-4000-8000-000000000051","revision":1,"title":"Review","meeting_date":"2026-09-09","transcript":"Private transcript","project_ids":["97000000-0000-4000-8000-000000000021"],"sections":[{"heading":"Progress","text":"Reviewed documents","basis":"verified"}]}')$$,'save complete draft');
SELECT throws_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','save','{"id":"97000000-0000-4000-8000-000000000051","revision":1}')$$,'P0001','This meeting changed. Reload before saving your edits.','stale revision rejected');
SELECT throws_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','save','{"id":"97000000-0000-4000-8000-000000000051","revision":2,"title":"Review","meeting_date":"2026-09-09","project_ids":["97000000-0000-4000-8000-000000000022"],"sections":[]}')$$,'P0001','Meeting projects must belong to this client','cross-client project rejected');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','action','{"meeting_id":"97000000-0000-4000-8000-000000000051","project_id":"97000000-0000-4000-8000-000000000021","title":"Confirm access","assignee_id":"97000000-0000-4000-8000-000000000002","assignee_name":"Owner"}')$$,'create action through shared workflow');
SELECT is((SELECT count(*)::int FROM workflow_instances WHERE record_type='client_meeting_action'),1,'shared engine instance exists');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','action',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0)||'{"assignee_id":""}'::jsonb)$$,'unassign open action');
SELECT ok((SELECT current_assignee_id IS NULL FROM workflow_instances WHERE record_type='client_meeting_action'),'shared workflow clears previous assignee');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','action',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0)||'{"assignee_id":"97000000-0000-4000-8000-000000000002"}'::jsonb)$$,'reassign open action');
SELECT is((SELECT current_assignee_id::text FROM workflow_instances WHERE record_type='client_meeting_action'),'97000000-0000-4000-8000-000000000002','shared workflow and checklist assignees match');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','publish','{"id":"97000000-0000-4000-8000-000000000051","revision":5}')$$,'release approved snapshot');
SELECT ok(NOT EXISTS(SELECT 1 FROM client_meeting_publications WHERE snapshot::text LIKE '%Private transcript%'),'published snapshot excludes transcript');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"97000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT ok(NOT client_meeting_can_edit('97000000-0000-4000-8000-000000000011'),'owner cannot edit internal drafts');
SELECT is((SELECT count(*)::int FROM client_meetings),0,'draft rows invisible to client');
SELECT ok(NOT client_meeting_can_read('97000000-0000-4000-8000-000000000012'),'other client not accessible');
SELECT is(jsonb_array_length(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'publications'),1,'client can read released meeting');
SELECT is((SELECT count(*)::int FROM client_meeting_actions),0,'client cannot read raw action source fields');
SELECT ok(NOT ((client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0) ? 'source_quote'),'curated actions omit source quotes');
SELECT is(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'delivery','null'::jsonb,'client cannot read email recipients');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','comment',jsonb_build_object('id',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0->>'id'),'body','Access arranged'))$$,'client can post update');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','submit',jsonb_build_object('id',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0->>'id')))$$,'assigned client submits completion');
SELECT is(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0->>'state','open','client submission does not close action');
SELECT throws_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','confirm',jsonb_build_object('id',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0->>'id')))$$,'P0001','Meeting edit permission required','client cannot confirm closure');
SELECT throws_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','schedule','{}')$$,'P0001','Meeting edit permission required','client cannot change email recipients');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"sub":"97000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','confirm',jsonb_build_object('id',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0->>'id')))$$,'staff confirms completion');
SELECT is(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0->>'state','closed','confirmed status persisted');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','action',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'actions'->0)||'{"title":"Revised access instructions"}'::jsonb)$$,'staff can edit existing action with its project and revision');
SELECT lives_ok($$SELECT client_meeting_command('97000000-0000-4000-8000-000000000011','save',(client_meeting_bundle('97000000-0000-4000-8000-000000000011')->'meetings'->0)||'{"title":"Internal amendment"}'::jsonb); SELECT 1 / CASE WHEN (SELECT snapshot->>'title' FROM client_meeting_publications LIMIT 1)='Review' THEN 1 ELSE 0 END$$,'draft edits do not overwrite released report');
RESET ROLE;
SELECT ok(claim_client_meeting_delivery((SELECT id FROM client_meeting_publications LIMIT 1),'2026-09-11') IS NOT NULL,'first delivery claims approved publication');
SELECT ok(claim_client_meeting_delivery((SELECT id FROM client_meeting_publications LIMIT 1),'2026-09-11') IS NULL,'concurrent delivery cannot claim twice');
SELECT ok(claim_client_meeting_delivery((SELECT id FROM client_meeting_publications LIMIT 1),'2026-09-18') IS NULL,'unchanged publication is not resent next week');
SELECT throws_ok($$SELECT agent_client_meeting((SELECT workspace_id FROM clients WHERE id='97000000-0000-4000-8000-000000000011'),'97000000-0000-4000-8000-000000000001','97000000-0000-4000-8000-000000000011','publish','{}')$$,'P0001','Agent access is draft-only','agent cannot publish through service wrapper');
SELECT * FROM finish();
ROLLBACK;
